def df_to_text_table(df, cols=None, floatfmt=None, max_width=120):
    if cols is not None:
        df=df[cols]
    df2=df.copy()
    for c in df2.columns:
        if pd.api.types.is_float_dtype(df2[c]):
            if floatfmt is None:
                df2[c]=df2[c].map(lambda x: "" if pd.isna(x) else f"{x:.3f}")
            else:
                df2[c]=df2[c].map(lambda x: "" if pd.isna(x) else floatfmt.format(x))
        else:
            df2[c]=df2[c].astype(str)
    # column widths
    widths={c:max(len(c), df2[c].map(len).max()) for c in df2.columns}
    header=" | ".join([c.ljust(widths[c]) for c in df2.columns])
    sep="-+-".join(['-'*widths[c] for c in df2.columns])
    rows=[]
    for _,r in df2.iterrows():
        rows.append(" | ".join([r[c].ljust(widths[c]) for c in df2.columns]))
    return "\n".join([header, sep]+rows)

