def format_table(df, cols, floatfmt="{:+.1f}"):
    # convert to strings with formatting for floats
    out=[]
    # determine column widths
    rows=[]
    for _,r in df.iterrows():
        row=[]
        for c in cols:
            v=r[c]
            if isinstance(v,(float,np.floating)):
                if 'delta' in c:
                    s=floatfmt.format(v)
                elif c in ('distance',):
                    s=f"{v:.2f}"
                else:
                    s=f"{v:.0f}" if abs(v-round(v))<1e-9 else f"{v:.2f}"
            else:
                s=str(v)
            row.append(s)
        rows.append(row)
    widths=[max(len(str(c)), max(len(row[i]) for row in rows)) for i,c in enumerate(cols)]
    header=" | ".join(str(c).ljust(widths[i]) for i,c in enumerate(cols))
    sep="-+-".join("-"*widths[i] for i in range(len(cols)))
    out=[header,sep]
    for row in rows:
        out.append(" | ".join(row[i].ljust(widths[i]) for i in range(len(cols))))
    return "\n".join(out)

