from numpy.linalg import lstsq
def slope(df, bm, day_start=20, day_end=34):
    sub=df[(df['day']>=day_start)&(df['day']<=day_end)][['day',bm]].dropna()
    x=sub['day'].to_numpy()
    y=sub[bm].to_numpy()
    if len(x)<2:
        return np.nan, len(x)
    # fit y = a + b*x
    A=np.vstack([np.ones_like(x), x]).T
    b=lstsq(A,y,rcond=None)[0][1]
    return b, len(x)

