def format_table(df):
    # create a plain text table with fixed widths
    # round values
    dff=df.copy()
    # rounding
    for col in dff.columns[1:]:
        if 'oxygen' in col:
            dff[col]=dff[col].map(lambda x: f"{x:,.1f}")
        else:
            dff[col]=dff[col].map(lambda x: f"{x:,.3f}")
    # compute col widths
    cols=dff.columns.tolist()
    widths=[max(len(str(col)), dff[col].astype(str).map(len).max()) for col in cols]
    # build lines
    header=" | ".join(str(col).ljust(w) for col,w in zip(cols,widths))
    sep="-+-".join("-"*w for w in widths)
    lines=[header,sep]
    for _,row in dff.iterrows():
        line=" | ".join(str(row[col]).ljust(w) for col,w in zip(cols,widths))
        lines.append(line)
    return "\n".join(lines)

