def first_death_by_col(df):
    death_cols=[c for c in df.columns if c.endswith('_death')]
    res={}
    for c in death_cols:
        idxs=df.index[df[c]==1].tolist()
        res[c]=int(df.loc[idxs[0],'day']) if idxs else None
    return res
